{"path": "textutils.py", "content": "import re
from collections import Counter

# A word is a run of letters, digits and apostrophes (underscore excluded).
_WORD_RE = re.compile(r"(?:[^\W_]|')+")


def words(text):
    return text.split()


def word_count(text):
    """Map each lower-cased word in text to its number of occurrences.

    Words are runs of letters, digits and apostrophes; everything else
    (punctuation, whitespace) separates words.
    """
    return dict(Counter(_WORD_RE.findall(text.lower())))
"}

